// Sketch: online ICA 3x3 with tanh nonlinearity
let W = randomOrthogonalMatrix(3)
for each frame X (3x1):
  let Y = W @ X
  let g = tanh(Y)
  // simplified gradient update
  let dW = eta * ( (1 - g * g.T) @ X.T )
  W = W + dW
  // decorrelate rows
  W = symmetrize(W)
```

